styles:
.reader-quote {
  font-style: normal;
  color: #7a9a7a;
  text-shadow: 0 0 6px rgba(122, 154, 122, 0.3);
  letter-spacing: 0.5px;
}
.reader-ellipsis {
  letter-spacing: 6px;
  opacity: 0.3;
  color: #6a8a6a;
}
.reader-dash {
  letter-spacing: 3px;
  opacity: 0.4;
  color: #556b55;
}
.reader-speak {
  color: #8a9a8a;
  font-weight: 600;
}
.reader-body :deep(.reader-dropcap) {
  float: left;
  font-size: 3em;
  line-height: 0.75;
  padding-right: 8px;
  padding-top: 4px;
  color: #5a7a5a;
  font-weight: 700;
  filter: blur(0.2px);
}
